/* Stark IntraTheater by Stark. World timeline: eras and events, sorted by year (negative = BCE / years ago).
   Strict JSON sits between each JSON marker and END marker (tests/test_data.py reads it). */
window.SIT_DATA = window.SIT_DATA || {};
window.SIT_DATA.eras = /*JSON:eras*/[
{"id": "deep", "name": "Deep Past", "start": -3400000, "end": -12000, "color": "#9a7b5b", "blurb": "Our ancestors learn to make tools, use fire and spread across the planet."},
{"id": "farmers", "name": "First Farmers", "start": -12000, "end": -3500, "color": "#7f9a5b", "blurb": "People settle down, plant crops, tame animals and build the first villages and towns."},
{"id": "ancient", "name": "Ancient Civilizations", "start": -3500, "end": -800, "color": "#c08a3e", "blurb": "Writing, cities, kings and pyramids appear along great rivers."},
{"id": "classical", "name": "Classical World", "start": -800, "end": 500, "color": "#b5654a", "blurb": "Great empires and big ideas: philosophy, democracy and world religions."},
{"id": "postclassical", "name": "Post-Classical World", "start": 500, "end": 1450, "color": "#7a6aa8", "blurb": "Faiths and trade routes link continents; empires rise from Mali to Mongolia."},
{"id": "earlymodern", "name": "Early Modern", "start": 1450, "end": 1750, "color": "#4f8a8b", "blurb": "Ocean voyages join the world together, for better and for worse; science takes off."},
{"id": "revolutions", "name": "Age of Revolutions", "start": 1750, "end": 1914, "color": "#a8505e", "blurb": "Machines, railways and revolutions change how people live and who rules them."},
{"id": "worldwars", "name": "World Wars and Cold War", "start": 1914, "end": 1991, "color": "#5f6f8f", "blurb": "Two world wars, new nations, the space race and a divided world."},
{"id": "today", "name": "Our Times", "start": 1991, "end": 2030, "color": "#3f8f6a", "blurb": "The web, a connected planet and shared challenges like climate and pandemics."}
]/*END*/;
window.SIT_DATA.events = /*JSON:events*/[
{"id": "lucy", "year": -3200000, "date": "c. 3.2 million years ago", "title": "Lucy walks upright", "region": "Africa", "era": "deep", "icon": "🦴", "kid": "In Ethiopia, scientists found the bones of “Lucy”, an early human relative who lived about 3.2 million years ago. She walked on two legs but was only about as tall as a 7-year-old.", "adult": "Lucy is a partial skeleton of Australopithecus afarensis found at Hadar, Ethiopia, in 1974 by Donald Johanson's team. Her pelvis and knee show she walked upright, while her small brain shows that walking on two legs came long before big brains. She was named after the Beatles song “Lucy in the Sky with Diamonds”, played at the camp."},
{"id": "first-tools", "year": -2600000, "date": "c. 2.6 million years ago", "title": "The first stone tools", "region": "Africa", "era": "deep", "icon": "🪨", "kid": "Early human relatives in East Africa learned to chip stones into sharp tools for cutting food. It was one of the very first big inventions!", "adult": "The Oldowan toolkit, named after Olduvai Gorge in Tanzania, appears about 2.6 million years ago at Gona, Ethiopia: sharp flakes struck from river cobbles and used to butcher animals. Older finds at Lomekwi, Kenya, about 3.3 million years old, suggest tool making began even earlier, though how to interpret them is still discussed."},
{"id": "homo-erectus", "year": -1800000, "date": "c. 1.8 million years ago", "title": "Leaving Africa for the first time", "region": "Global", "era": "deep", "icon": "🚶", "kid": "A human relative called Homo erectus became the first to walk out of Africa, reaching places as far away as Georgia and, later, China and Indonesia.", "adult": "Fossils at Dmanisi in Georgia, about 1.8 million years old, are the oldest widely accepted hominin remains outside Africa. Homo erectus, taller and longer-legged than earlier species, spread across much of Asia, reaching Java and China. It survived for well over a million years, one of the longest-lived human species."},
{"id": "fire", "year": -1000000, "date": "c. 1 million years ago", "title": "Taming fire", "region": "Africa", "era": "deep", "icon": "🔥", "kid": "People learned to control fire. Fire kept them warm, scared away animals and let them cook their food.", "adult": "Burned bone and plant ash in Wonderwerk Cave, South Africa, about one million years old, is some of the earliest strong evidence of controlled fire. Regular, everyday use becomes clear at many sites by roughly 400,000 years ago. Cooking made food easier to digest, and some researchers argue it helped fuel the growth of larger brains."},
{"id": "homo-sapiens", "year": -300000, "date": "c. 300,000 years ago", "title": "Our species appears", "region": "Africa", "era": "deep", "icon": "👣", "kid": "The oldest known fossils of our own species, Homo sapiens, were found in Morocco. They are about 300,000 years old.", "adult": "Skulls and teeth from Jebel Irhoud, Morocco, dated to roughly 300,000 years ago, show faces much like ours but brains with a longer, lower shape. Together with finds from Ethiopia and South Africa, they suggest Homo sapiens emerged across Africa as a connected population rather than in a single “cradle”."},
{"id": "out-of-africa", "year": -60000, "date": "c. 70,000–50,000 years ago", "title": "Spreading across the world", "region": "Global", "era": "deep", "icon": "🌍", "kid": "Groups of modern humans walked out of Africa and, over thousands of years, spread into Asia, Europe and beyond.", "adult": "Genetic evidence shows that nearly all people living outside Africa descend from populations that dispersed roughly 70,000 to 50,000 years ago, after some earlier, smaller movements. On the way they met and had children with Neanderthals and Denisovans: most people with non-African ancestry carry about 1 to 2 percent Neanderthal DNA."},
{"id": "australia", "year": -50000, "date": "at least 50,000 years ago", "title": "First peoples reach Australia", "region": "Oceania", "era": "deep", "icon": "🛶", "kid": "People crossed the sea to reach Australia. Aboriginal Australians have one of the oldest continuous cultures on Earth.", "adult": "Reaching Sahul (Australia and New Guinea, joined by low sea levels) still required sea crossings from Southeast Asia. Most researchers accept arrival by at least 50,000 years ago, and some sites, such as Madjedbebe in Arnhem Land, have been dated to around 65,000 years. Aboriginal and Torres Strait Islander cultures are among the oldest continuous living cultures in the world."},
{"id": "cave-art", "year": -45000, "date": "c. 45,000 years ago and later", "title": "Painting in caves", "region": "Global", "era": "deep", "icon": "🎨", "kid": "People painted animals on cave walls with red and black colours. Some of the oldest paintings are in Indonesia and France.", "adult": "A painted warty pig in Leang Tedongnge cave on Sulawesi, Indonesia, has been dated to at least 45,500 years ago. In France, Chauvet Cave holds lions, horses and rhinos drawn about 36,000 years ago with a skill that surprised researchers. Such finds show that symbolic art was widespread, not a sudden European invention."},
{"id": "neanderthals", "year": -40000, "date": "c. 40,000 years ago", "title": "The last Neanderthals", "region": "Europe", "era": "deep", "icon": "🦣", "kid": "Neanderthals were a kind of human who lived in Europe and Asia for a very long time. They made tools, hunted big animals and used fire, but disappeared around 40,000 years ago.", "adult": "Neanderthals lived across Europe and western Asia for hundreds of thousands of years. They probably buried some of their dead, made pigments and glues, and hunted large game. Most of their populations vanish from the record around 40,000 years ago, a few thousand years after modern humans arrived; competition, small populations, climate swings and interbreeding are all discussed as causes."},
{"id": "americas", "year": -15000, "date": "by c. 15,000 years ago", "title": "People reach the Americas", "region": "Americas", "era": "deep", "icon": "🦬", "kid": "People reached the Americas from Asia, probably walking across a land bridge or travelling along the coast by boat. They spread all the way to the tip of South America.", "adult": "During the last Ice Age, low sea levels exposed Beringia, linking Siberia and Alaska. Monte Verde in Chile shows people far to the south by about 14,500 years ago, which suggests a route along the Pacific coast. Fossil footprints at White Sands, New Mexico, dated to about 23,000–21,000 years ago, point to an even earlier arrival, though some researchers still question those dates."},
{"id": "gobekli-tepe", "year": -9500, "date": "c. 9500 BCE", "title": "Göbekli Tepe", "region": "Middle East", "era": "farmers", "icon": "🗿", "kid": "In what is now Türkiye, people carved huge stone pillars with foxes, boars and birds, and set them in great rings. It is one of the oldest monuments in the world.", "adult": "Göbekli Tepe, in southeastern Türkiye, was built from about 9500 BCE by people who still lived mainly by hunting and gathering. Its T-shaped limestone pillars, the largest over 5 metres tall, are carved with animals. Its discovery suggested to many scholars that big communal gatherings may have helped push people toward settled life and farming, not only the other way round."},
{"id": "farming", "year": -9000, "date": "c. 9500–8500 BCE", "title": "Farming begins", "region": "Middle East", "era": "farmers", "icon": "🌾", "kid": "In the Fertile Crescent, people began planting wheat and barley and keeping sheep and goats. Farming meant they could stay in one place and build villages.", "adult": "In the arc of land from the Levant to the Zagros Mountains, people domesticated wheat, barley, lentils, peas, sheep, goats, pigs and cattle over roughly the 10th to 8th millennia BCE. Farming was invented independently in several other regions, including China, New Guinea, Mesoamerica, the Andes and parts of Africa. It brought more food and larger populations, but also new diseases and harder work."},
{"id": "catalhoyuk", "year": -7100, "date": "c. 7100–5700 BCE", "title": "Çatalhöyük, a town of rooftops", "region": "Middle East", "era": "farmers", "icon": "🏘️", "kid": "Çatalhöyük was a big early town where houses were packed so tightly that people walked across the rooftops and climbed in through holes in the roof!", "adult": "This settlement on the Konya Plain in Türkiye housed several thousand people at its height. Mud-brick houses shared walls and were entered by ladders through the roof. Wall paintings, plastered bull horns and burials beneath the floors give a rare view of daily and ritual life in an early farming community."},
{"id": "maize", "year": -7000, "date": "c. 7000 BCE", "title": "Maize is domesticated", "region": "Americas", "era": "farmers", "icon": "🌽", "kid": "In southern Mexico, farmers slowly changed a wild grass called teosinte into maize, or corn. Over thousands of years the tiny cobs grew bigger and bigger.", "adult": "Genetic and archaeological work traces maize to teosinte in the Balsas River valley of Mexico about 9,000 years ago. Early cobs were only a few centimetres long. Maize, beans and squash became the staple crops of the Americas, and after 1492 maize spread worldwide; today it is one of the most produced crops on Earth."},
{"id": "rice", "year": -7000, "date": "by c. 7000 BCE", "title": "Rice farming in China", "region": "East Asia", "era": "farmers", "icon": "🍚", "kid": "Along China's Yangtze River, people learned to grow rice. Today rice is a main food for more than half the people on Earth.", "adult": "Rice cultivation developed gradually in the Yangtze valley; sites there show people cultivating rice by around 7000 BCE, and fully domesticated rice became established over the following thousands of years. Further north, along the Yellow River, people farmed millet. These two farming traditions formed the foundation of early Chinese civilization."},
{"id": "varna", "year": -4500, "date": "c. 4600–4200 BCE", "title": "The gold of Varna", "region": "Europe", "era": "farmers", "icon": "🥇", "kid": "Near the Black Sea in Bulgaria, archaeologists found graves filled with gold jewellery. It is the oldest worked gold treasure ever found.", "adult": "The Varna Necropolis, discovered in 1972, contains more than 3,000 gold objects. One burial held far more gold than all the rest, suggesting that some people had already become much richer and more powerful than others, among the earliest clear signs of social hierarchy in Europe."},
{"id": "wheel", "year": -3500, "date": "c. 3500 BCE", "title": "The wheel", "region": "Global", "era": "ancient", "icon": "🐂", "kid": "People invented the wheel! At first it was used for carts pulled by oxen and for making pots, not for fast cars.", "adult": "Wheeled vehicles appear almost at once, around 3500–3300 BCE, from Mesopotamia to the steppe north of the Black Sea and central Europe, which makes the exact place of invention unclear. One of the oldest surviving wooden wheels, from the Ljubljana Marshes in Slovenia, is about 5,000 years old. The potter's wheel in Mesopotamia may be even older."},
{"id": "writing", "year": -3200, "date": "c. 3400–3100 BCE", "title": "Writing is invented", "region": "Middle East", "era": "ancient", "icon": "✍️", "kid": "In Sumer, in today's Iraq, people pressed wedge shapes into clay tablets to keep track of grain and animals. This was one of the first kinds of writing, called cuneiform.", "adult": "Cuneiform grew out of accounting records in cities such as Uruk, becoming true writing in the late 4th millennium BCE. Egyptian hieroglyphs appear at almost the same time. Writing was later invented independently in China (by about 1200 BCE) and in Mesoamerica, and it changed how laws, history and stories could be kept."},
{"id": "egypt-unified", "year": -3100, "date": "c. 3100 BCE", "title": "Egypt becomes one kingdom", "region": "Africa", "era": "ancient", "icon": "🏺", "kid": "Upper and Lower Egypt were joined into one kingdom ruled by a king, later called a pharaoh. Egypt's kingdom lasted for about 3,000 years.", "adult": "Tradition credits a king called Menes; many scholars link the unification to Narmer, whose ceremonial palette shows him wearing the crowns of both Upper and Lower Egypt. The state that followed, organized around the Nile flood, writing and divine kingship, endured with interruptions for some three thousand years until the Roman conquest in 30 BCE."},
{"id": "stonehenge", "year": -3000, "date": "c. 3000–2500 BCE", "title": "Stonehenge", "region": "Europe", "era": "ancient", "icon": "🌄", "kid": "In England, people built Stonehenge, a giant circle of standing stones. Some stones were dragged from Wales, more than 200 km away!", "adult": "Stonehenge began around 3000 BCE as a circular ditch and bank; the giant sarsen stones were raised around 2500 BCE. The smaller bluestones came from the Preseli Hills in Wales, and the Altar Stone, recent research shows, from northeast Scotland. The monument is aligned with the midsummer sunrise and midwinter sunset."},
{"id": "indus", "year": -2600, "date": "c. 2600–1900 BCE", "title": "Cities of the Indus", "region": "South & Southeast Asia", "era": "ancient", "icon": "🧱", "kid": "In today's Pakistan and India, people built neat cities like Mohenjo-daro with straight streets, brick houses and drains for dirty water.", "adult": "The mature Harappan civilization covered a larger area than Egypt or Mesopotamia. Its cities used standardized bricks and weights, grid-like streets and remarkable drainage. Its script, found on thousands of small seals, has never been deciphered, so much about its rulers and beliefs remains unknown."},
{"id": "great-pyramid", "year": -2560, "date": "c. 2560 BCE", "title": "The Great Pyramid", "region": "Africa", "era": "ancient", "icon": "🔺", "kid": "Egyptians built the Great Pyramid of Giza for King Khufu. It was the tallest building in the world for almost 4,000 years!", "adult": "Built for the Fourth Dynasty king Khufu, the pyramid originally stood about 146 metres high and held the record as the tallest human-made structure for some 3,800 years. Workers' villages, bakeries and tombs found nearby show it was built by organized crews who were housed and fed, not by masses of slaves as once popularly imagined."},
{"id": "akkad", "year": -2300, "date": "c. 2300 BCE", "title": "Sargon's empire", "region": "Middle East", "era": "ancient", "icon": "⚔️", "kid": "Sargon of Akkad conquered many cities in Mesopotamia and ruled them together. Many historians call it the first empire.", "adult": "Sargon (reigned c. 2334–2279 BCE in one common chronology) united the Sumerian city-states with Akkad, creating a state that reached from the Persian Gulf toward the Mediterranean. His daughter Enheduanna, high priestess at Ur, is the earliest author in history known by name."},
{"id": "hammurabi", "year": -1754, "date": "c. 1754 BCE", "title": "Hammurabi's laws", "region": "Middle East", "era": "ancient", "icon": "⚖️", "kid": "King Hammurabi of Babylon had nearly 300 laws carved on a tall black stone so everyone could see the rules.", "adult": "The stele, now in the Louvre, records about 282 laws on trade, family, property and injury, with punishments that often depended on social class. It was not the first law code (the Code of Ur-Nammu is older), but it is the most complete to survive from early Mesopotamia."},
{"id": "shang", "year": -1600, "date": "c. 1600 BCE", "title": "China's Shang dynasty", "region": "East Asia", "era": "ancient", "icon": "🐢", "kid": "The Shang kings ruled in northern China. They asked their ancestors questions by writing on turtle shells and bones, the oldest Chinese writing we know.", "adult": "The Shang is the earliest Chinese dynasty confirmed by its own written records. Oracle-bone inscriptions from its last capital at Anyang (from about 1250 BCE) record divination about harvests, war and weather, and the script is a direct ancestor of modern Chinese characters. The Shang were also masters of bronze casting."},
{"id": "tutankhamun", "year": -1332, "date": "c. 1332–1323 BCE", "title": "The boy king Tutankhamun", "region": "Africa", "era": "ancient", "icon": "👑", "kid": "Tutankhamun became pharaoh of Egypt when he was only about 9 years old. His tomb, full of golden treasures, was found almost untouched in 1922.", "adult": "Tutankhamun was a fairly minor king who died at around 19, and his reign restored Egypt's traditional gods after the religious upheaval of Akhenaten. His fame comes from Howard Carter's 1922 discovery of his nearly intact tomb in the Valley of the Kings, with more than 5,000 objects including the gold funerary mask."},
{"id": "olmec", "year": -1200, "date": "c. 1200 BCE", "title": "The Olmec", "region": "Americas", "era": "ancient", "icon": "🗿", "kid": "On the Gulf Coast of Mexico, the Olmec people carved giant stone heads, some taller than a grown-up.", "adult": "The Olmec, centred first at San Lorenzo and later at La Venta, created one of Mesoamerica's earliest complex societies. Their colossal basalt heads, probably portraits of rulers, weigh many tonnes. Many later Mesoamerican traditions, including the ritual ballgame and certain gods, may have roots in Olmec culture."},
{"id": "bronze-collapse", "year": -1190, "date": "c. 1200–1150 BCE", "title": "The Bronze Age collapse", "region": "Middle East", "era": "ancient", "icon": "🏚️", "kid": "Around this time many great kingdoms around the eastern Mediterranean fell apart. Cities were burned, and long-distance trade stopped for a while.", "adult": "Within a few decades the Hittite Empire, the Mycenaean palaces of Greece and cities such as Ugarit collapsed, and Egypt was weakened by attacks from groups it called the Sea Peoples. Historians now see several causes working together: drought, earthquakes, broken trade networks, rebellions and migration."},
{"id": "alphabet", "year": -1050, "date": "c. 1050 BCE", "title": "The Phoenician alphabet", "region": "Middle East", "era": "ancient", "icon": "🔤", "kid": "Phoenician traders used a short alphabet of 22 letters. It was passed on to the Greeks and later to the Romans, and grew into the letters you are reading now!", "adult": "Earlier alphabetic writing appears in Egypt and Sinai in the 2nd millennium BCE, but the standardized Phoenician alphabet of about 1050 BCE spread widely through Mediterranean trade. The Greeks added vowels; the Etruscans and Romans adapted it into the Latin alphabet, while its Aramaic descendant led to the Hebrew and Arabic scripts."},
{"id": "lapita", "year": -1000, "date": "c. 1100–800 BCE", "title": "Lapita voyagers sail the Pacific", "region": "Oceania", "era": "ancient", "icon": "⛵", "kid": "Amazing sailors called the Lapita people crossed the open Pacific Ocean in canoes and settled islands like Fiji, Tonga and Samoa.", "adult": "Known from their distinctive stamped pottery, the Lapita spread from the Bismarck Archipelago near New Guinea into remote Oceania, reaching Vanuatu, New Caledonia, Fiji, Tonga and Samoa between about 1100 and 800 BCE. Their descendants became the Polynesians, who would later settle the islands of the eastern Pacific."},
{"id": "olympics", "year": -776, "date": "776 BCE (traditional date)", "title": "The first Olympic Games", "region": "Europe", "era": "classical", "icon": "🏅", "kid": "The ancient Greeks held sports games at Olympia to honour the god Zeus. The first race on record was a sprint of about 190 metres.", "adult": "Greek tradition dates the first Olympiad to 776 BCE, and Greeks later counted time in four-year Olympiads. The festival grew to include wrestling, boxing, chariot racing and the pankration, with athletes from across the Greek world. The ancient games continued for over a thousand years, ending in the late 4th or 5th century CE."},
{"id": "rome-founded", "year": -753, "date": "753 BCE (legend)", "title": "Rome's legendary founding", "region": "Europe", "era": "classical", "icon": "🐺", "kid": "According to legend, twin brothers Romulus and Remus, raised by a wolf, founded the city of Rome. Romans celebrated the city's birthday every year on 21 April.", "adult": "The date 753 BCE was worked out by the Roman scholar Varro, and the story of Romulus and Remus is a founding myth. Archaeology shows villages on the Palatine Hill from around the 10th–8th centuries BCE that gradually grew into a city. Rome was ruled by kings until the Republic was founded, by tradition in 509 BCE."},
{"id": "persia", "year": -550, "date": "c. 550 BCE", "title": "Cyrus founds the Persian Empire", "region": "Middle East", "era": "classical", "icon": "🏛️", "kid": "Cyrus the Great built the Persian Empire, which became the biggest empire the world had seen so far.", "adult": "Cyrus II overthrew the Medes around 550 BCE, then conquered Lydia and, in 539 BCE, Babylon. The Achaemenid Empire later stretched from Egypt and Thrace to the Indus, linked by royal roads and a relay of mounted messengers. Cyrus allowed peoples deported to Babylon, including the Judeans, to return home, which made him honoured in the Hebrew Bible."},
{"id": "confucius", "year": -520, "date": "551–479 BCE (traditional dates)", "title": "Confucius teaches", "region": "East Asia", "era": "classical", "icon": "📜", "kid": "Confucius was a teacher in China who said people should be kind, respect their families and keep learning. His ideas are still important today.", "adult": "Kong Qiu, known as Kongzi or Confucius, served as a minor official and teacher in the state of Lu. His sayings, collected by followers in the Analects, stress ritual propriety, respect for parents, humaneness (ren) and government by moral example. Confucianism became state orthodoxy under the Han dynasty and shaped East Asian education and government for two thousand years."},
{"id": "democracy", "year": -508, "date": "508–507 BCE", "title": "Democracy in Athens", "region": "Europe", "era": "classical", "icon": "🗳️", "kid": "In Athens, Greece, citizens began voting on laws themselves. The word democracy means “rule by the people”.", "adult": "The reforms of Cleisthenes reorganized Athenians into new tribes and gave power to an assembly of citizens. It was a direct democracy: citizens voted in person, and many officials were chosen by lot. But “citizens” meant adult free men; women, enslaved people and foreigners were excluded."},
{"id": "buddha", "year": -480, "date": "c. 5th century BCE (dates debated)", "title": "The Buddha", "region": "South & Southeast Asia", "era": "classical", "icon": "☸️", "kid": "In northern India, a prince named Siddhartha Gautama left his palace to understand why people suffer. He became known as the Buddha, the “awakened one”.", "adult": "Most scholars place the Buddha's life in the 5th century BCE, though older traditions put it earlier. He taught the Middle Way between luxury and harsh self-denial, the Four Noble Truths and the Eightfold Path. Buddhism later spread to Sri Lanka, Southeast Asia, Central Asia, China, Korea and Japan."},
{"id": "alexander", "year": -334, "date": "334–323 BCE", "title": "Alexander the Great", "region": "Middle East", "era": "classical", "icon": "🐎", "kid": "Alexander, a young king from Macedonia, marched his army from Greece to Egypt and all the way to India in about ten years.", "adult": "Alexander crossed into Asia in 334 BCE, defeated the Persian king Darius III, founded Alexandria in Egypt and reached the Indus valley before his troops refused to go further. He died in Babylon in 323 BCE, aged 32. His empire split among his generals, but the Hellenistic kingdoms spread Greek language and culture across the Middle East for centuries."},
{"id": "meroe", "year": -300, "date": "c. 300 BCE–350 CE", "title": "The pyramids of Meroë", "region": "Africa", "era": "classical", "icon": "🔺", "kid": "In the kingdom of Kush, south of Egypt in today's Sudan, kings and queens were buried under steep pyramids. Sudan has even more pyramids than Egypt!", "adult": "The Kingdom of Kush had once ruled Egypt as its 25th Dynasty. From its later capital Meroë it built some 200 pyramids, traded in iron, gold and ivory, and developed its own Meroitic script, which can be read aloud but is still only partly understood. Powerful queens, known as kandakes, sometimes ruled in their own right."},
{"id": "ashoka", "year": -268, "date": "c. 268–232 BCE", "title": "Emperor Ashoka", "region": "South & Southeast Asia", "era": "classical", "icon": "🦁", "kid": "Ashoka ruled a huge empire in India. After a terrible war he felt so sorry that he chose peace and kindness, and had his ideas carved on pillars and rocks.", "adult": "The Mauryan emperor's conquest of Kalinga caused enormous loss of life, which, by his own inscriptions, filled him with remorse. He promoted dhamma, a code of moral conduct, supported Buddhism and sent envoys abroad. His Lion Capital at Sarnath is now the national emblem of India."},
{"id": "qin", "year": -221, "date": "221 BCE", "title": "China is unified", "region": "East Asia", "era": "classical", "icon": "🏯", "kid": "The First Emperor, Qin Shi Huang, joined China's warring kingdoms into one country. He was buried with an army of thousands of clay soldiers.", "adult": "Ying Zheng of Qin conquered the last rival states and took the new title Shi Huangdi, “First Emperor”. He standardized writing, weights, measures and coins, and linked earlier walls in the north. His dynasty fell within 15 years, but the unified imperial model lasted more than two thousand years. His tomb's Terracotta Army, found in 1974, has thousands of life-size figures."},
{"id": "silk-road", "year": -130, "date": "c. 130 BCE", "title": "The Silk Roads open", "region": "East Asia", "era": "classical", "icon": "🐫", "kid": "Traders with camels carried silk, spices and ideas back and forth across Asia, linking China with Persia, India and the Mediterranean.", "adult": "The journeys of the Han envoy Zhang Qian (c. 138–126 BCE) gave China direct knowledge of Central Asia and helped open the overland routes. They were never a single road but a shifting web of routes, carrying silk, horses, glass, paper, religions such as Buddhism, and also diseases. The name “Silk Road” was coined only in 1877 by the German geographer Ferdinand von Richthofen."},
{"id": "caesar", "year": -44, "date": "44 BCE", "title": "Julius Caesar is killed", "region": "Europe", "era": "classical", "icon": "🗡️", "kid": "Julius Caesar was a powerful Roman leader. Some senators feared he wanted to be king, so they attacked him on the Ides of March.", "adult": "After crossing the Rubicon in 49 BCE and winning a civil war, Caesar was named dictator for life. A group of senators led by Brutus and Cassius stabbed him in Rome on 15 March 44 BCE. Instead of saving the Republic, his murder set off new civil wars that ended with his adopted heir Octavian holding sole power."},
{"id": "augustus", "year": -27, "date": "27 BCE", "title": "Rome's first emperor", "region": "Europe", "era": "classical", "icon": "🏛️", "kid": "Octavian took the name Augustus and became the first Roman emperor. Rome would be ruled by emperors for hundreds of years.", "adult": "Augustus kept the outward forms of the Republic while holding real power, a system historians call the Principate. His reign began the Pax Romana, about two centuries of relative peace inside an empire that stretched from Britain and Spain to Egypt and Syria."},
{"id": "jesus", "year": 30, "date": "c. 30–33 CE", "title": "Jesus of Nazareth", "region": "Middle East", "era": "classical", "icon": "✝️", "kid": "Jesus, a Jewish teacher from Galilee, taught about love and forgiveness. His followers started Christianity, which became the world's largest religion.", "adult": "Jesus was crucified in Jerusalem under the Roman prefect Pontius Pilate, probably between 30 and 33 CE. His followers proclaimed that he had risen from the dead, and missionaries such as Paul spread the movement across the Roman world. Christianity grew from a small Jewish movement into the empire's favoured religion by the 4th century."},
{"id": "pompeii", "year": 79, "date": "79 CE", "title": "Vesuvius buries Pompeii", "region": "Europe", "era": "classical", "icon": "🌋", "kid": "The volcano Mount Vesuvius erupted and covered the Roman town of Pompeii in ash. Today we can walk its streets and see how Romans lived.", "adult": "The eruption buried Pompeii, Herculaneum and other towns. Pliny the Younger described it in letters, and his uncle, Pliny the Elder, died during a rescue attempt. Excavations since the 18th century have revealed houses, shops, graffiti and wall paintings, an unmatched snapshot of everyday Roman life."},
{"id": "paper", "year": 105, "date": "105 CE (traditional date)", "title": "Paper in China", "region": "East Asia", "era": "classical", "icon": "📄", "kid": "A Chinese official named Cai Lun is said to have made paper from tree bark, rags and old fishing nets. Paper was much cheaper than silk to write on.", "adult": "Han court records credit Cai Lun with presenting an improved papermaking method in 105 CE, though archaeology shows simpler paper existed in China more than two centuries earlier. Papermaking spread slowly westward, reaching the Islamic world by the 8th century and Europe by the 12th century."},
{"id": "maya", "year": 250, "date": "c. 250–900 CE", "title": "Maya cities flourish", "region": "Americas", "era": "classical", "icon": "🌿", "kid": "The Maya built great stone cities with pyramids in the rainforests of Central America. They had their own writing, calendars and a symbol for zero.", "adult": "During the Classic period, rival kingdoms such as Tikal, Calakmul, Palenque and Copán raised temples and carved monuments recording royal histories in a fully developed hieroglyphic script. Maya astronomers tracked Venus and predicted eclipses. Many southern lowland cities were abandoned in the 9th century, but the Maya people never disappeared; millions speak Maya languages today."},
{"id": "gupta", "year": 320, "date": "c. 320–550 CE", "title": "India's Gupta era", "region": "South & Southeast Asia", "era": "classical", "icon": "🔢", "kid": "Under the Gupta kings, Indian scholars made great discoveries in maths and science. They helped develop the number system with zero that we use today.", "adult": "The Gupta period is often called a classical age of Indian culture, with Sanskrit literature such as the works of Kalidasa. The mathematician-astronomer Aryabhata (born 476) used a place-value system and proposed that the Earth rotates on its axis. Indian decimal numerals later passed through the Islamic world to Europe as “Arabic numerals”."},
{"id": "constantinople", "year": 330, "date": "330 CE", "title": "Constantinople is founded", "region": "Europe", "era": "classical", "icon": "⛪", "kid": "Emperor Constantine built a new capital for the Roman Empire where Europe meets Asia. It was called Constantinople, and today it is Istanbul.", "adult": "Constantine, the first Roman emperor to embrace Christianity, rebuilt the Greek city of Byzantium and dedicated it in 330. The eastern Roman (Byzantine) Empire ruled from it for over 1,100 years, until the Ottoman conquest of 1453."},
{"id": "aksum", "year": 340, "date": "c. 340 CE", "title": "Aksum turns to Christianity", "region": "Africa", "era": "classical", "icon": "✝️", "kid": "In the Kingdom of Aksum, in today's Ethiopia and Eritrea, King Ezana became a Christian. Aksum was a rich trading kingdom with tall carved stone pillars.", "adult": "Aksum controlled Red Sea trade between the Roman world, Arabia and India, minted its own gold coins and raised huge granite stelae. King Ezana's adoption of Christianity in the 4th century made Aksum one of the first states to do so; Ethiopia's Orthodox Church traces its roots to this time."},
{"id": "rome-falls", "year": 476, "date": "476 CE", "title": "The Western Roman Empire ends", "region": "Europe", "era": "classical", "icon": "🏚️", "kid": "The last emperor in the western half of the Roman Empire was removed from power. The eastern half carried on for almost a thousand more years.", "adult": "The Germanic commander Odoacer deposed the young emperor Romulus Augustulus and did not appoint a successor. The date is symbolic: Rome's western provinces had been lost gradually over decades to migration, invasion, civil war and money troubles. Historians still debate whether to call it a “fall” or a transformation."},
{"id": "hagia-sophia", "year": 537, "date": "537 CE", "title": "Hagia Sophia", "region": "Europe", "era": "postclassical", "icon": "🕌", "kid": "Emperor Justinian built Hagia Sophia in Constantinople. Its giant dome seemed to float in the air, and it was the largest cathedral in the world for nearly a thousand years.", "adult": "Designed by Anthemius of Tralles and Isidore of Miletus and built in under six years, Hagia Sophia's dome rests on pendentives, a daring solution that influenced later architecture. After 1453 it became a mosque, in 1934 a museum, and in 2020 a mosque again."},
{"id": "tang", "year": 618, "date": "618 CE", "title": "The Tang dynasty", "region": "East Asia", "era": "postclassical", "icon": "🏮", "kid": "The Tang dynasty began a golden age in China, famous for poetry, painting and its busy capital Chang'an, one of the largest cities in the world.", "adult": "Tang China (618–907) was cosmopolitan: Chang'an held perhaps a million people and welcomed merchants, monks and envoys from across Asia. The period produced the poets Li Bai and Du Fu, expanded the civil-service examinations and saw woodblock printing develop; the Diamond Sutra of 868 is the oldest dated printed book."},
{"id": "hijra", "year": 622, "date": "622 CE", "title": "The Hijra and the rise of Islam", "region": "Middle East", "era": "postclassical", "icon": "🌙", "kid": "The Prophet Muhammad and his followers moved from Mecca to Medina. Muslims count the years of the Islamic calendar from this journey.", "adult": "Muhammad began preaching in Mecca around 610. Facing opposition, he and his followers migrated to Yathrib (Medina) in 622, the Hijra, where he led a growing community. Within a century of his death in 632, Muslim rule stretched from Spain to Central Asia."},
{"id": "zero", "year": 628, "date": "628 CE", "title": "Zero becomes a number", "region": "South & Southeast Asia", "era": "postclassical", "icon": "0️⃣", "kid": "Indian mathematician Brahmagupta wrote rules for using zero as a real number, like 3 + 0 = 3. That idea changed mathematics forever.", "adult": "Other cultures, including the Babylonians and the Maya, used a placeholder zero, but Brahmagupta's Brahmasphutasiddhanta is the first known text to treat zero as a number with rules for arithmetic, alongside negative numbers. (His rule for dividing by zero was later corrected.)"},
{"id": "baghdad", "year": 762, "date": "762 CE", "title": "Baghdad and the House of Wisdom", "region": "Middle East", "era": "postclassical", "icon": "📚", "kid": "The Abbasid caliphs built Baghdad as a round city. Scholars there translated books from Greek, Persian and Indian languages and made new discoveries.", "adult": "Caliph al-Mansur founded Baghdad in 762 as the Abbasid capital. Under later caliphs, scholars connected with the House of Wisdom translated Greek, Persian and Sanskrit works into Arabic. Al-Khwarizmi's book on algebra gave us the word “algebra”, and his name the word “algorithm”."},
{"id": "vikings", "year": 793, "date": "793 CE", "title": "The Viking Age begins", "region": "Europe", "era": "postclassical", "icon": "🪓", "kid": "Vikings from Scandinavia sailed their longships to raid the monastery at Lindisfarne in England. Vikings were also traders, farmers and explorers.", "adult": "The attack on Lindisfarne in 793 is the traditional start of the Viking Age. Norse seafarers raided and traded from Ireland to the Caspian Sea, founded settlements in Iceland, Normandy and Dublin, and travelled down Russian rivers to Constantinople. The period is usually said to end around 1066."},
{"id": "charlemagne", "year": 800, "date": "800 CE", "title": "Charlemagne is crowned emperor", "region": "Europe", "era": "postclassical", "icon": "👑", "kid": "On Christmas Day, the Pope crowned Charlemagne, King of the Franks, as emperor. He ruled much of western Europe and loved learning.", "adult": "Pope Leo III's coronation of Charlemagne revived the idea of a western Roman emperor and created lasting tension with Constantinople. Charlemagne's court supported the Carolingian Renaissance, copying classical texts in a clear new handwriting, Carolingian minuscule, the ancestor of our lowercase letters."},
{"id": "qarawiyyin", "year": 859, "date": "859 CE (traditional date)", "title": "Al-Qarawiyyin in Fez", "region": "Africa", "era": "postclassical", "icon": "🏫", "kid": "Fatima al-Fihri founded a mosque in Fez, Morocco, that grew into a famous place of learning. It is still open today.", "adult": "Founded, according to tradition, by Fatima al-Fihri, daughter of a wealthy merchant, al-Qarawiyyin became a major centre of learning in the Islamic world. It is often described, for example by Guinness World Records, as the oldest existing, continually operating educational institution, though it became a university in the modern sense only in 1963."},
{"id": "leif", "year": 1000, "date": "c. 1000 CE", "title": "Norse sailors in North America", "region": "Americas", "era": "postclassical", "icon": "🧭", "kid": "Leif Erikson and other Norse sailors reached North America about 500 years before Columbus. They built a small camp in Newfoundland, Canada.", "adult": "Icelandic sagas describe voyages to “Vinland”. In the 1960s, Helge and Anne Stine Ingstad excavated Norse buildings at L'Anse aux Meadows in Newfoundland, and in 2021 tree-ring analysis showed that wood there was cut with metal tools in the year 1021. The settlement was short-lived."},
{"id": "cahokia", "year": 1050, "date": "c. 1050–1350 CE", "title": "Cahokia", "region": "Americas", "era": "postclassical", "icon": "⛰️", "kid": "Near today's St. Louis, USA, people built Cahokia, a big city with huge earth mounds. The biggest, Monks Mound, is about 30 metres tall.", "adult": "Cahokia was the largest city of the Mississippian culture and the largest pre-Columbian settlement north of Mexico, with perhaps 10,000–20,000 people at its peak around 1100. The base of Monks Mound covers an area comparable to the Great Pyramid of Giza. The city declined after 1200 and was largely abandoned by 1350."},
{"id": "hastings", "year": 1066, "date": "1066", "title": "The Norman Conquest", "region": "Europe", "era": "postclassical", "icon": "🏹", "kid": "William of Normandy won the Battle of Hastings and became King of England. The story is shown on the Bayeux Tapestry, an embroidery about 70 metres long.", "adult": "William's victory over Harold Godwinson transformed England: a new French-speaking elite, castles across the land and the great survey known as Domesday Book (1086). Thousands of French words entered English, which is why English has pairs like “cow” and “beef”."},
{"id": "crusades", "year": 1096, "date": "1096–1099", "title": "The First Crusade", "region": "Middle East", "era": "postclassical", "icon": "⚔️", "kid": "Armies from Europe marched to the Middle East to capture Jerusalem. These wars, called the Crusades, went on for about 200 years.", "adult": "Called by Pope Urban II in 1095, the First Crusade captured Jerusalem in 1099 with a massacre of its Muslim and Jewish inhabitants and founded the Crusader states. Later crusades were less successful: Saladin retook Jerusalem in 1187, and the last mainland Crusader stronghold, Acre, fell in 1291."},
{"id": "angkor", "year": 1113, "date": "c. 1113–1150", "title": "Angkor Wat", "region": "South & Southeast Asia", "era": "postclassical", "icon": "🛕", "kid": "In Cambodia, a Khmer king built Angkor Wat, the largest religious monument in the world. It appears on Cambodia's flag.", "adult": "King Suryavarman II built Angkor Wat as a Hindu temple dedicated to Vishnu; it later became a Buddhist temple. Angkor was the centre of the Khmer Empire, and airborne laser mapping (lidar) has shown it was a vast, spread-out city with complex waterworks, possibly the most extensive pre-industrial urban area in the world."},
{"id": "genghis", "year": 1206, "date": "1206", "title": "The Mongol Empire", "region": "East Asia", "era": "postclassical", "icon": "🐎", "kid": "Temüjin united the Mongol tribes and was named Genghis Khan. His riders built the largest connected land empire in history.", "adult": "From 1206 the Mongols conquered northern China, Central Asia, Persia and the Russian principalities, at enormous human cost. At its height in the late 13th century the empire stretched from the Pacific to eastern Europe. The “Pax Mongolica” that followed also eased trade and travel across Eurasia."},
{"id": "magna-carta", "year": 1215, "date": "1215", "title": "Magna Carta", "region": "Europe", "era": "postclassical", "icon": "📜", "kid": "English barons made King John agree to a list of rules called Magna Carta. It said that even the king had to follow the law.", "adult": "Sealed at Runnymede, the charter was mostly about the barons' rights and was annulled by the Pope within weeks, but reissued versions became part of English law. Its clauses against imprisonment without lawful judgment and against selling justice inspired later ideas of due process, including in the US Constitution."},
{"id": "mali", "year": 1235, "date": "c. 1235", "title": "The Mali Empire", "region": "Africa", "era": "postclassical", "icon": "🦁", "kid": "Sundiata Keita, called the Lion of Mali, founded the Mali Empire in West Africa. Griots, storytellers who sing history, still tell his story.", "adult": "After defeating the Sosso king Sumanguru at the Battle of Kirina, Sundiata built an empire based on gold, salt and trade across the Sahara. The Epic of Sundiata, passed down orally by griots, is a major source. Mali's cities, including Timbuktu and Djenné, became centres of Islamic learning."},
{"id": "aotearoa", "year": 1280, "date": "c. 1250–1300", "title": "Polynesians reach Aotearoa", "region": "Oceania", "era": "postclassical", "icon": "🛶", "kid": "Polynesian voyagers, finding their way by stars, waves and birds, sailed to New Zealand. Their descendants are the Māori people.", "adult": "New Zealand was among the last large land masses settled by humans. Radiocarbon dates point to arrival around 1250–1300, completing a Polynesian expansion that also reached Hawaiʻi and Rapa Nui (Easter Island). Māori traditions name the great canoes (waka) of the ancestral voyages."},
{"id": "great-zimbabwe", "year": 1300, "date": "c. 1100–1450", "title": "Great Zimbabwe", "region": "Africa", "era": "postclassical", "icon": "🏰", "kid": "In southern Africa, the Shona people's ancestors built Great Zimbabwe, a city of tall stone walls made without any mortar. The country Zimbabwe is named after it.", "adult": "Great Zimbabwe peaked in the 13th–15th centuries as the capital of a state that traded gold and ivory to the Swahili coast, receiving Chinese porcelain and Persian glass in return. For decades colonial authorities falsely claimed Africans could not have built it; archaeology firmly shows it was built by ancestors of the Shona."},
{"id": "mansa-musa", "year": 1324, "date": "1324", "title": "Mansa Musa's pilgrimage", "region": "Africa", "era": "postclassical", "icon": "🪙", "kid": "Mansa Musa, the king of Mali, travelled to Mecca with a huge caravan carrying gold. He gave so much away in Cairo that the value of gold there fell!", "adult": "The Arab historian al-Umari recorded that Musa's spending in Cairo depressed the value of gold there for years. He brought back scholars and the architect credited with Timbuktu's Djinguereber Mosque. The 1375 Catalan Atlas shows him holding a golden nugget, a sign of how far Mali's wealth was known."},
{"id": "tenochtitlan", "year": 1325, "date": "1325 (traditional date)", "title": "Tenochtitlan is founded", "region": "Americas", "era": "postclassical", "icon": "🦅", "kid": "The Mexica (Aztec) people built their capital, Tenochtitlan, on an island in a lake. Legend says they saw an eagle on a cactus there, and it is on Mexico's flag today!", "adult": "Tenochtitlan grew into one of the largest cities in the world, with perhaps 200,000 people by 1519, linked to the shore by causeways and fed by chinampas, raised fields built in the lake. Mexico City stands on its ruins, and excavations of the Templo Mayor have revealed its great temple."},
{"id": "black-death", "year": 1347, "date": "1347–1351", "title": "The Black Death", "region": "Europe", "era": "postclassical", "icon": "🐀", "kid": "A terrible disease called the plague spread to Europe, the Middle East and North Africa. Very many people died, and life changed for those who survived.", "adult": "Caused by the bacterium Yersinia pestis and spread by fleas and possibly by people, the pandemic killed roughly a third to a half of Europe's population, with heavy losses in the Middle East and North Africa too. Labour shortages afterwards raised wages for survivors and weakened serfdom in western Europe."},
{"id": "ming", "year": 1368, "date": "1368", "title": "The Ming dynasty", "region": "East Asia", "era": "postclassical", "icon": "🧱", "kid": "The Ming dynasty ruled China for nearly 300 years. The Ming built most of the Great Wall you see in photos and the Forbidden City palace in Beijing.", "adult": "Founded by Zhu Yuanzhang, a former peasant and monk who drove out the Mongol Yuan dynasty, the Ming moved the capital to Beijing, where the Forbidden City was completed in 1420. Most surviving sections of the Great Wall date from the Ming, which also produced famous blue-and-white porcelain."},
{"id": "zheng-he", "year": 1405, "date": "1405–1433", "title": "Zheng He's treasure fleets", "region": "East Asia", "era": "postclassical", "icon": "🚢", "kid": "Admiral Zheng He led huge fleets of Chinese ships across the Indian Ocean, as far as East Africa. A giraffe was even brought back to China!", "adult": "Seven Ming expeditions carried tens of thousands of men to Southeast Asia, India, Arabia and the Swahili coast, displaying imperial power and gathering tribute. Records describe the largest “treasure ships” as enormous, though their exact size is debated. After 1433 the court ended the voyages."},
{"id": "pachacuti", "year": 1438, "date": "c. 1438", "title": "The Inca Empire rises", "region": "Americas", "era": "postclassical", "icon": "🦙", "kid": "The Inca ruler Pachacuti began building a mighty empire in the Andes mountains of South America. The Inca built roads, rope bridges and Machu Picchu.", "adult": "From Cusco, Pachacuti and his successors created Tawantinsuyu, the largest empire in the pre-Columbian Americas, stretching some 4,000 km along the Andes. Without wheeled transport or a writing system as we know it, the Inca ran it with roads, relay runners and knotted-cord records called khipu. Machu Picchu was probably built as an estate for Pachacuti around 1450."},
{"id": "printing", "year": 1440, "date": "c. 1440", "title": "Gutenberg's printing press", "region": "Europe", "era": "postclassical", "icon": "📖", "kid": "Johannes Gutenberg made a printing press with metal letters that could be moved around. Books became much faster and cheaper to make.", "adult": "Movable type was not new: Bi Sheng used ceramic type in China around 1040, and in Korea the Jikji was printed with metal type in 1377. Gutenberg combined a hand mould for casting type, oil-based ink and an adapted screw press. By 1500, European presses had produced millions of books, speeding up the Renaissance, the Reformation and the Scientific Revolution."},
{"id": "constantinople-falls", "year": 1453, "date": "1453", "title": "The fall of Constantinople", "region": "Europe", "era": "earlymodern", "icon": "🕌", "kid": "The Ottoman sultan Mehmed II captured Constantinople with huge cannons. The city became the Ottoman capital, later called Istanbul.", "adult": "The 53-day siege ended the Byzantine Empire, the last remnant of the Roman state. Mehmed II used enormous bronze cannons against the city's famous land walls. Greek scholars who fled westward brought manuscripts that enriched the Italian Renaissance, and the Ottoman Empire endured until 1922."},
{"id": "columbus", "year": 1492, "date": "1492", "title": "Columbus reaches the Caribbean", "region": "Americas", "era": "earlymodern", "icon": "⛵", "kid": "Christopher Columbus sailed west from Spain hoping to reach Asia, but landed on islands in the Caribbean. It connected Europe and the Americas, with huge effects on both.", "adult": "Columbus's voyages began lasting contact between Europe and the Americas and the “Columbian Exchange” of crops, animals and diseases. Maize, potatoes and tomatoes transformed diets worldwide, while smallpox and other diseases, along with violence and forced labour, devastated Indigenous peoples, beginning with the Taíno of the Caribbean."},
{"id": "da-gama", "year": 1498, "date": "1498", "title": "A sea route to India", "region": "South & Southeast Asia", "era": "earlymodern", "icon": "🌶️", "kid": "Portuguese sailor Vasco da Gama sailed around Africa and reached India. Now Europeans could buy spices without going overland.", "adult": "Da Gama rounded the Cape of Good Hope and, with the help of a local pilot from the East African coast, crossed the Arabian Sea to Calicut. Portugal used the new route to build a network of fortified trading posts, challenging the long-established Indian Ocean trade of Arab, Gujarati, Swahili and Chinese merchants."},
{"id": "sistine", "year": 1508, "date": "1508–1512", "title": "Michelangelo paints the Sistine Chapel", "region": "Europe", "era": "earlymodern", "icon": "🎨", "kid": "Michelangelo spent four years painting the ceiling of the Sistine Chapel in Rome, standing on scaffolding high above the floor.", "adult": "Commissioned by Pope Julius II, the ceiling's scenes from Genesis, including the Creation of Adam, became icons of the High Renaissance, alongside Leonardo's Mona Lisa and Raphael's School of Athens from the same years. Michelangelo, who saw himself as a sculptor, returned decades later to paint the Last Judgment on the altar wall."},
{"id": "reformation", "year": 1517, "date": "1517", "title": "The Reformation begins", "region": "Europe", "era": "earlymodern", "icon": "📜", "kid": "Martin Luther, a German monk, wrote 95 points arguing with the Church. His ideas spread quickly thanks to printing and split Western Christianity.", "adult": "Luther's Ninety-five Theses attacked the sale of indulgences. Printed pamphlets spread his ideas fast, and Protestant churches formed across northern Europe. The resulting conflicts, culminating in the Thirty Years' War (1618–1648), reshaped European politics, and the Catholic Church answered with reforms of its own."},
{"id": "magellan", "year": 1519, "date": "1519–1522", "title": "The first voyage around the world", "region": "Global", "era": "earlymodern", "icon": "🌐", "kid": "Ferdinand Magellan's ships set out to sail around the whole world. Magellan died on the way, but one ship made it home after three years.", "adult": "Of about 270 men and five ships, only the Victoria, captained by Juan Sebastián Elcano, returned to Spain in 1522 with 18 of the original crew. Magellan was killed at Mactan in the Philippines in 1521 fighting the forces of the local chief Lapulapu, now honoured as a Filipino hero. The voyage revealed the vast size of the Pacific."},
{"id": "slave-trade", "year": 1520, "date": "c. 1500s–1860s", "title": "The transatlantic slave trade", "region": "Africa", "era": "earlymodern", "icon": "⛓️", "kid": "For more than 300 years, millions of African people were captured, taken across the ocean in ships and forced to work as enslaved people in the Americas. Many people fought hard to end slavery.", "adult": "Between the early 1500s and the 1860s about 12.5 million Africans were forced onto ships bound for the Americas, and nearly 2 million died during the Middle Passage. Enslaved people resisted constantly, through revolts, escape and keeping their cultures alive. The trade enriched European ports and plantation economies and shaped the societies of the Americas and West Africa to this day."},
{"id": "tenochtitlan-falls", "year": 1521, "date": "1521", "title": "The fall of Tenochtitlan", "region": "Americas", "era": "earlymodern", "icon": "🦅", "kid": "Spanish soldiers led by Hernán Cortés and their many Indigenous allies captured the Aztec capital after a long siege. Smallpox had also struck the city.", "adult": "Cortés had only a few hundred Spaniards; tens of thousands of Tlaxcalan and other Indigenous allies, who resented Mexica rule, made the conquest possible. A smallpox epidemic in 1520 killed many inhabitants, including the emperor Cuitláhuac. The city fell in August 1521 after a 75-day siege and became the capital of New Spain."},
{"id": "mughal", "year": 1526, "date": "1526", "title": "The Mughal Empire", "region": "South & Southeast Asia", "era": "earlymodern", "icon": "🐘", "kid": "Babur won the Battle of Panipat and founded the Mughal Empire in India. Later Mughal emperors built amazing buildings like the Taj Mahal.", "adult": "Babur, a descendant of both Timur and Genghis Khan, used field guns and cavalry tactics to defeat the Delhi Sultanate. Under Akbar (1556–1605) the empire became one of the richest in the world, with a tolerant policy toward its many faiths, and Persian-influenced art and architecture flourished."},
{"id": "copernicus", "year": 1543, "date": "1543", "title": "The Sun at the centre", "region": "Europe", "era": "earlymodern", "icon": "☀️", "kid": "Nicolaus Copernicus wrote that the Earth goes around the Sun, not the Sun around the Earth. Many people did not believe him at first.", "adult": "On the Revolutions of the Heavenly Spheres was published in the year Copernicus died. The ancient Greek Aristarchus of Samos had proposed a Sun-centred model, but Copernicus worked it out mathematically. Galileo's telescope and Kepler's laws later gave it strong support, and Newton explained why it works."},
{"id": "tokugawa", "year": 1603, "date": "1603", "title": "Peace in Edo Japan", "region": "East Asia", "era": "earlymodern", "icon": "🗾", "kid": "Tokugawa Ieyasu became shogun and brought peace to Japan after a long time of war. Japan stayed mostly peaceful for about 250 years.", "adult": "The Tokugawa shogunate ruled from Edo (now Tokyo) until 1868. It strictly limited foreign contact, allowing chiefly Dutch and Chinese trade at Nagasaki. The long peace encouraged towns, commerce, kabuki theatre and woodblock prints such as Hokusai's Great Wave."},
{"id": "galileo", "year": 1610, "date": "1610", "title": "Galileo's telescope", "region": "Europe", "era": "earlymodern", "icon": "🔭", "kid": "Galileo pointed a telescope at the sky and saw mountains on the Moon and four moons going around Jupiter!", "adult": "In The Starry Messenger (1610) Galileo described lunar mountains, countless stars in the Milky Way and Jupiter's four large moons. His later support for the Sun-centred system led to his trial by the Inquisition in 1633 and house arrest for the rest of his life."},
{"id": "taj-mahal", "year": 1632, "date": "c. 1632–1653", "title": "The Taj Mahal", "region": "South & Southeast Asia", "era": "earlymodern", "icon": "🕌", "kid": "Emperor Shah Jahan built the Taj Mahal in Agra, India, as a tomb for his wife Mumtaz Mahal. It is made of shining white marble.", "adult": "Some 20,000 workers built the complex over about two decades, with the main mausoleum largely finished around 1643. Its symmetry, gardens and inlaid semi-precious stones make it the masterpiece of Mughal architecture; it became a UNESCO World Heritage Site in 1983."},
{"id": "newton", "year": 1687, "date": "1687", "title": "Newton's laws of motion", "region": "Europe", "era": "earlymodern", "icon": "🍎", "kid": "Isaac Newton explained that the same force, gravity, makes an apple fall and keeps the Moon going around the Earth.", "adult": "Newton's Principia set out three laws of motion and the law of universal gravitation, uniting earthly and heavenly physics in one mathematical system. It explained planetary orbits and tides and remained the foundation of physics until Einstein's relativity refined it in the early 20th century."},
{"id": "industrial", "year": 1760, "date": "c. 1760–1840", "title": "The Industrial Revolution", "region": "Europe", "era": "revolutions", "icon": "🏭", "kid": "In Britain, people built machines powered by water and steam to spin cloth and pump water. Factories and big cities grew fast.", "adult": "Historians point to cheap coal, costly labour, colonial trade and a culture of practical invention to explain why Britain went first. Key steps included the spinning jenny, the water frame and James Watt's improved steam engine (patented 1769). Industry brought huge growth in goods and population, but also child labour, crowded cities and pollution, and spread to Europe, North America and Japan in the 19th century."},
{"id": "us-independence", "year": 1776, "date": "1776", "title": "American independence", "region": "Americas", "era": "revolutions", "icon": "🔔", "kid": "Thirteen British colonies in North America declared that they were a new country: the United States of America.", "adult": "The Declaration of Independence, drafted mainly by Thomas Jefferson and adopted on 4 July 1776, proclaimed that “all men are created equal”, while slavery remained legal in every colony. The war ended with British recognition of independence in 1783, and the Constitution of 1787 created a lasting federal republic."},
{"id": "first-fleet", "year": 1788, "date": "1788", "title": "Britain colonizes Australia", "region": "Oceania", "era": "revolutions", "icon": "⚓", "kid": "British ships called the First Fleet arrived at Sydney Cove with convicts and soldiers. Aboriginal people had lived there for tens of thousands of years.", "adult": "Captain Arthur Phillip's fleet of 11 ships founded a penal colony on Gadigal land in January 1788. Colonization brought disease, dispossession and violence to Aboriginal and Torres Strait Islander peoples. 26 January is Australia Day, a date many Indigenous Australians mark as Invasion Day or Survival Day."},
{"id": "french-revolution", "year": 1789, "date": "1789", "title": "The French Revolution", "region": "Europe", "era": "revolutions", "icon": "📣", "kid": "The people of France rose up against their king, stormed a prison called the Bastille and declared that all citizens should have rights.", "adult": "Financial crisis, food shortages and Enlightenment ideas led to the storming of the Bastille on 14 July 1789 and the Declaration of the Rights of Man and of the Citizen. The monarchy was abolished in 1792, the Terror of 1793–94 executed thousands, and the revolutionary decade ended with Napoleon's seizure of power in 1799. Its ideals of liberty, equality and national sovereignty spread worldwide."},
{"id": "haiti", "year": 1791, "date": "1791–1804", "title": "The Haitian Revolution", "region": "Americas", "era": "revolutions", "icon": "✊", "kid": "Enslaved people in the French colony of Saint-Domingue rose up and won their freedom. In 1804 they founded Haiti, the first country created by people who freed themselves from slavery.", "adult": "Beginning with a massive revolt in August 1791 and led by figures such as Toussaint Louverture and Jean-Jacques Dessalines, the revolution defeated French, Spanish and British forces. Haiti became the second independent nation in the Americas and abolished slavery permanently, but in 1825 France forced it to pay a huge indemnity for its independence, a burden that lasted for generations."},
{"id": "bolivar", "year": 1810, "date": "1810–1825", "title": "Latin American independence", "region": "Americas", "era": "revolutions", "icon": "🏇", "kid": "People in Spanish America fought for independence. Leaders like Simón Bolívar and José de San Martín helped free countries from Venezuela to Argentina.", "adult": "Napoleon's invasion of Spain in 1808 triggered a crisis of authority across Spain's American empire. Over some fifteen years of war, Bolívar, San Martín, Sucre, O'Higgins and many others won independence for most of Spanish South America. Mexico won independence in 1821, and Brazil declared independence from Portugal in 1822."},
{"id": "railway", "year": 1825, "date": "1825", "title": "The first public steam railway", "region": "Europe", "era": "revolutions", "icon": "🚂", "kid": "The Stockton and Darlington Railway in England became the first public railway to use steam locomotives. Soon trains were carrying people everywhere.", "adult": "George Stephenson's Locomotion No. 1 hauled the opening train. The Liverpool and Manchester Railway (1830) was the first intercity line run entirely by steam locomotives on a timetable. Railways shrank travel times, led to standardized time zones and moved coal, grain and people on an unprecedented scale."},
{"id": "darwin", "year": 1859, "date": "1859", "title": "Darwin's Origin of Species", "region": "Europe", "era": "revolutions", "icon": "🐦", "kid": "Charles Darwin explained how living things slowly change over many generations, which is called evolution. He got many ideas on a long voyage aboard a ship called the Beagle.", "adult": "Darwin and Alfred Russel Wallace independently proposed evolution by natural selection, presented jointly in 1858. On the Origin of Species set out the evidence the following year. Combined with genetics in the 20th century, it became the central organizing idea of modern biology."},
{"id": "meiji", "year": 1868, "date": "1868", "title": "The Meiji Restoration", "region": "East Asia", "era": "revolutions", "icon": "🌸", "kid": "Japan's emperor was restored to power, and Japan changed very quickly, building railways, factories and schools in just a few decades.", "adult": "After US warships under Matthew Perry forced Japan to open its ports in 1853–54, the Tokugawa shogunate collapsed. The new Meiji government abolished the samurai class, created a conscript army and modern schools, and industrialized rapidly. By 1905 Japan had defeated Russia, the first time in the modern era that an Asian power defeated a European great power in a major war."},
{"id": "berlin-conference", "year": 1884, "date": "1884–1885", "title": "The Scramble for Africa", "region": "Africa", "era": "revolutions", "icon": "🗺️", "kid": "European leaders met in Berlin and made rules for taking over Africa, without asking any Africans. By 1914 almost all of Africa was ruled by Europeans.", "adult": "The Berlin Conference set rules for claiming African territory and recognized King Leopold II's Congo Free State, where forced rubber collection later caused mass death. By 1914 only Ethiopia, which defeated Italy at Adwa in 1896, and Liberia remained independent. Colonial borders drawn in this era still shape African states today."},
{"id": "brazil-abolition", "year": 1888, "date": "1888", "title": "Brazil abolishes slavery", "region": "Americas", "era": "revolutions", "icon": "🕊️", "kid": "Brazil passed the Golden Law, freeing all enslaved people. It was the last country in the Americas to end slavery.", "adult": "Brazil had received more enslaved Africans than any other country, around 4.9 million. The Lei Áurea, signed by Princess Isabel on 13 May 1888, came after decades of resistance, escapes and abolitionist campaigns. Britain had ended slavery in most of its colonies from 1834, and the United States through the 13th Amendment in 1865."},
{"id": "nz-suffrage", "year": 1893, "date": "1893", "title": "Women win the vote in New Zealand", "region": "Oceania", "era": "revolutions", "icon": "🗳️", "kid": "New Zealand became the first self-governing country where all adult women could vote in national elections.", "adult": "Petitions organized by Kate Sheppard and others gathered nearly 32,000 signatures. Māori women voted too. Women could not stand for Parliament until 1919. Other countries followed slowly: Finland in 1906 also let women stand for office, the UK granted equal voting in 1928, and Switzerland only in 1971 at the national level."},
{"id": "wright", "year": 1903, "date": "1903", "title": "The first powered flight", "region": "Americas", "era": "revolutions", "icon": "✈️", "kid": "The Wright brothers flew the first powered, controlled aeroplane at Kitty Hawk, USA. The first flight lasted just 12 seconds!", "adult": "On 17 December 1903 Orville Wright flew about 37 metres in 12 seconds; Wilbur's best flight that day covered about 260 metres in 59 seconds. Their key breakthrough was control around all three axes. Within 66 years, humans would walk on the Moon."},
{"id": "ww1", "year": 1914, "date": "1914–1918", "title": "The First World War", "region": "Europe", "era": "worldwars", "icon": "🎖️", "kid": "A huge war began in Europe and spread around the world. Soldiers fought from trenches, and millions of people died. Many people wear poppies to remember them.", "adult": "Triggered by the assassination of Archduke Franz Ferdinand in Sarajevo, the war pitted the Allies against the Central Powers. Machine guns, artillery and poison gas made the Western Front a deadly stalemate. About 9 million soldiers and millions of civilians died, and the war brought down four empires: the German, Austro-Hungarian, Russian and Ottoman."},
{"id": "russian-revolution", "year": 1917, "date": "1917", "title": "The Russian Revolution", "region": "Europe", "era": "worldwars", "icon": "🚩", "kid": "The people of Russia overthrew their emperor, the tsar. Later the Bolsheviks, led by Lenin, took power and created the Soviet Union.", "adult": "War losses and hunger led to the February Revolution, which ended the monarchy. In October the Bolsheviks seized power, then won a brutal civil war and founded the Union of Soviet Socialist Republics in 1922. Under Stalin, the one-party state industrialized rapidly at the cost of famine, labour camps and millions of deaths."},
{"id": "flu-1918", "year": 1918, "date": "1918–1920", "title": "The 1918 influenza pandemic", "region": "Global", "era": "worldwars", "icon": "😷", "kid": "A very serious flu spread around the world. Doctors and nurses worked hard, and people learned how important it is to stop germs from spreading.", "adult": "The H1N1 influenza pandemic infected perhaps a third of the world's population and killed tens of millions of people, often estimated at about 50 million, more than the First World War. Unusually, it hit healthy young adults hard. Wartime censorship meant that neutral Spain reported it openly, which is why it was misleadingly called the “Spanish flu”."},
{"id": "penicillin", "year": 1928, "date": "1928", "title": "Penicillin is discovered", "region": "Europe", "era": "worldwars", "icon": "🧫", "kid": "Alexander Fleming noticed that a mould had killed germs on a dish in his lab. This led to penicillin, the first antibiotic medicine.", "adult": "Fleming's observation became a usable drug only after Howard Florey, Ernst Chain, Norman Heatley and colleagues at Oxford purified it around 1940–41. Mass production in the US and Britain made it widely available to Allied troops by 1944. Antibiotics have saved many millions of lives, though overuse now drives resistance."},
{"id": "depression", "year": 1929, "date": "1929", "title": "The Great Depression", "region": "Global", "era": "worldwars", "icon": "📉", "kid": "Many banks and businesses in the United States closed, and the trouble spread around the world. Lots of people lost their jobs and had very little money.", "adult": "The Wall Street Crash of October 1929 helped trigger the worst economic depression of the industrial era. Bank failures, collapsing trade and tight money pushed US unemployment to about 25 percent by 1933. The crisis fuelled extremist politics in Europe and led to new government programmes such as the US New Deal."},
{"id": "ww2", "year": 1939, "date": "1939–1945", "title": "The Second World War", "region": "Global", "era": "worldwars", "icon": "🕯️", "kid": "The biggest war in history was fought across Europe, Asia, Africa and the oceans. During the war the Nazis murdered millions of Jewish people and others in the Holocaust. We remember them so it never happens again.", "adult": "Germany's invasion of Poland in 1939 began the war in Europe; Japan had been at war in China since 1937. Some 70–85 million people died, most of them civilians. Nazi Germany murdered about six million Jews in the Holocaust, as well as Roma, disabled people and others. The war ended in Europe in May 1945 and in Asia after the US atomic bombings of Hiroshima and Nagasaki and the Soviet attack on Manchuria in August 1945."},
{"id": "un", "year": 1945, "date": "1945", "title": "The United Nations is founded", "region": "Global", "era": "worldwars", "icon": "🤝", "kid": "After the war, countries joined together to form the United Nations, a place to talk about problems and work for peace. Today it has 193 member countries.", "adult": "The UN Charter was signed in San Francisco in June 1945 by 50 countries (Poland signed later as an original member, making 51) and took effect on 24 October 1945. The Security Council's five permanent members hold a veto. UN agencies such as UNICEF, the World Health Organization and the World Food Programme work on children, health and hunger."},
{"id": "india", "year": 1947, "date": "1947", "title": "Indian independence and Partition", "region": "South & Southeast Asia", "era": "worldwars", "icon": "🪔", "kid": "After a long, mostly peaceful struggle led by people like Mahatma Gandhi, India became independent from Britain. Pakistan was created as a separate country at the same time.", "adult": "Independence came on 14–15 August 1947 with the partition of British India into India and Pakistan (which then included today's Bangladesh). Partition caused one of the largest migrations in history, some 15 million people, and violence that killed hundreds of thousands, perhaps up to two million. Gandhi was assassinated in January 1948."},
{"id": "udhr", "year": 1948, "date": "1948", "title": "The Universal Declaration of Human Rights", "region": "Global", "era": "worldwars", "icon": "📜", "kid": "The United Nations agreed on a list of rights that belong to every person in the world, like the right to go to school and to be treated fairly.", "adult": "Drafted by a committee chaired by Eleanor Roosevelt, with key roles for René Cassin, P. C. Chang, Charles Malik and others, the Declaration was adopted on 10 December 1948, now Human Rights Day. It is not a treaty, but it inspired binding covenants and many national constitutions, and it is among the most translated documents in the world."},
{"id": "prc", "year": 1949, "date": "1949", "title": "The People's Republic of China", "region": "East Asia", "era": "worldwars", "icon": "🏮", "kid": "After a long civil war, Mao Zedong's Communist Party took control of mainland China and founded the People's Republic of China.", "adult": "Mao proclaimed the People's Republic on 1 October 1949, while the Nationalist government retreated to Taiwan. The Great Leap Forward (1958–62) led to a famine that killed tens of millions, and the Cultural Revolution (1966–76) caused further upheaval. Economic reforms from 1978 under Deng Xiaoping began decades of rapid growth."},
{"id": "dna", "year": 1953, "date": "1953", "title": "The DNA double helix", "region": "Europe", "era": "worldwars", "icon": "🧬", "kid": "Scientists discovered that DNA, the instructions inside our cells, is shaped like a twisted ladder called a double helix.", "adult": "James Watson and Francis Crick built their model in Cambridge using X-ray data from King's College London, including Rosalind Franklin and Raymond Gosling's “Photo 51”, which was shown to Watson without Franklin's knowledge. The structure showed how genetic information can be copied. Watson, Crick and Maurice Wilkins received the 1962 Nobel Prize; Franklin had died in 1958."},
{"id": "civil-rights", "year": 1955, "date": "1955–1968", "title": "The US civil rights movement", "region": "Americas", "era": "worldwars", "icon": "🚌", "kid": "Rosa Parks refused to give up her bus seat, and Martin Luther King Jr. and many others peacefully protested for equal rights for Black Americans.", "adult": "The Montgomery bus boycott (1955–56), sit-ins, Freedom Rides and the 1963 March on Washington, where King gave his “I Have a Dream” speech, challenged legal segregation. The Civil Rights Act of 1964 and the Voting Rights Act of 1965 outlawed key forms of discrimination. King was assassinated in 1968."},
{"id": "sputnik", "year": 1957, "date": "1957", "title": "Sputnik and the Space Age", "region": "Global", "era": "worldwars", "icon": "🛰️", "kid": "The Soviet Union launched Sputnik 1, the first satellite to orbit the Earth. It was about the size of a beach ball and went beep-beep on the radio.", "adult": "Sputnik's launch on 4 October 1957 shocked the United States and began the Space Race; NASA was created in 1958 in response. In 1961 Yuri Gagarin became the first human in space, and in 1963 Valentina Tereshkova became the first woman in space."},
{"id": "africa-1960", "year": 1960, "date": "1960", "title": "The Year of Africa", "region": "Africa", "era": "worldwars", "icon": "✨", "kid": "In 1960, seventeen African countries became independent, which is why it is called the Year of Africa.", "adult": "Ghana's independence in 1957 under Kwame Nkrumah had inspired the continent. In 1960 alone, 17 countries, including Nigeria, Senegal, Madagascar and the Congo, gained independence, most of them from France and others from Britain, Belgium and Italy. Decolonization was often negotiated, but in Algeria (independent in 1962) and Kenya it followed bitter wars."},
{"id": "moon", "year": 1969, "date": "1969", "title": "Humans walk on the Moon", "region": "Global", "era": "worldwars", "icon": "🌕", "kid": "Astronauts Neil Armstrong and Buzz Aldrin landed on the Moon and walked on it. Armstrong said, “That's one small step for man, one giant leap for mankind.”", "adult": "Apollo 11 landed on 20 July 1969 while Michael Collins orbited above. Hundreds of millions of people watched on television. Twelve astronauts walked on the Moon between 1969 and 1972, and no one has been back since."},
{"id": "berlin-wall", "year": 1989, "date": "1989", "title": "The Berlin Wall falls", "region": "Europe", "era": "worldwars", "icon": "🔨", "kid": "Crowds of people in Berlin, Germany, broke through the wall that had divided their city for 28 years. Families who had been apart could finally meet again.", "adult": "Built by East Germany in 1961, the Wall symbolized the Cold War division of Europe. On 9 November 1989, after mass protests and a confused announcement about new travel rules, crowds forced the checkpoints open. Revolutions swept Eastern Europe that year, and Germany reunified on 3 October 1990."},
{"id": "www", "year": 1991, "date": "1989–1991", "title": "The World Wide Web", "region": "Europe", "era": "today", "icon": "💻", "kid": "Tim Berners-Lee, working at a science lab called CERN, invented the World Wide Web, a way to link pages together on the internet.", "adult": "Berners-Lee proposed the web in 1989 and built the first browser and server in 1990; it became publicly available in 1991, and CERN released the technology royalty-free in 1993. The underlying internet grew from ARPANET (1969) and the TCP/IP protocols adopted in 1983."},
{"id": "ussr-ends", "year": 1991, "date": "1991", "title": "The Soviet Union ends", "region": "Europe", "era": "today", "icon": "🧊", "kid": "The Soviet Union broke up into 15 separate countries, including Russia and Ukraine. The long Cold War between the USSR and the USA came to an end.", "adult": "Mikhail Gorbachev's reforms, glasnost (openness) and perestroika (restructuring), loosened control, and national movements grew. After a failed hardline coup in August 1991, the republics declared independence, and the USSR was formally dissolved on 26 December 1991."},
{"id": "mandela", "year": 1994, "date": "1994", "title": "Nelson Mandela is elected", "region": "Africa", "era": "today", "icon": "🌈", "kid": "South Africa held its first election in which people of all races could vote. Nelson Mandela, who had spent 27 years in prison, became president.", "adult": "Apartheid, a system of legal racial segregation imposed from 1948, was dismantled through negotiations after Mandela's release in 1990. The April 1994 election brought the African National Congress to power. The Truth and Reconciliation Commission later heard testimony about abuses of the apartheid era."},
{"id": "genome", "year": 2003, "date": "2003", "title": "The human genome is read", "region": "Global", "era": "today", "icon": "🧬", "kid": "Scientists from many countries finished reading the whole instruction book of human DNA, which has about 3 billion letters.", "adult": "The international Human Genome Project, launched in 1990, announced completion in April 2003; the last gaps were closed in 2022. Sequencing that once cost billions of dollars now costs far less than a thousand, transforming medicine, ancestry research and the study of human history through ancient DNA."},
{"id": "paris-agreement", "year": 2015, "date": "2015", "title": "The Paris climate agreement", "region": "Global", "era": "today", "icon": "🌡️", "kid": "Almost every country agreed to work together to slow down climate change by cutting the pollution that warms the Earth.", "adult": "Adopted at the COP21 conference, the agreement aims to hold warming well below 2 °C above pre-industrial levels and to pursue efforts to limit it to 1.5 °C. Each country sets its own targets, called nationally determined contributions, and is expected to strengthen them every five years."},
{"id": "covid", "year": 2020, "date": "2020", "title": "The COVID-19 pandemic", "region": "Global", "era": "today", "icon": "🦠", "kid": "A new virus spread around the world. Schools and shops closed for a while, and scientists made vaccines faster than ever before.", "adult": "The World Health Organization declared a pandemic on 11 March 2020. Lockdowns reshaped work and school worldwide. Vaccines were developed and authorized within a year, including the first widely used mRNA vaccines. WHO estimated about 15 million excess deaths in 2020 and 2021 alone."},
{"id": "jwst", "year": 2021, "date": "2021", "title": "The James Webb Space Telescope", "region": "Global", "era": "today", "icon": "🌌", "kid": "A giant space telescope with a golden mirror was launched. It can see some of the very first galaxies that formed after the Big Bang.", "adult": "Launched on 25 December 2021, Webb observes mainly in infrared light from about 1.5 million km from Earth. Its 6.5-metre segmented mirror lets it study galaxies from the universe's first few hundred million years, the atmospheres of planets around other stars and the birth of stars."}
]/*END*/;
